# Run inside browser-harness against the local preview.
result=js(r'''(async()=>{
// Baseline renderer contracts; citywide.browser.py covers the rollout default.
const legacyCity=plots=>kit.createCityBuildings(plots,{rollout:false});
const T=await import('three'),office=await import('./js/world/office-slice.js'),kit=await import('./js/world/building-kit.js'),{townhouseMaterials}=await import('./js/world/building-slice-materials.js'),{stops}=await import('./js/content.js'),{routePoints,routeCurve}=await import('./js/world/layout.js'),{buildCity}=await import('./js/world/city.js');
const check=(v,m)=>{if(!v)throw Error(m)},pts=routePoints(stops.length),plots=[];buildCity(()=>{},stops,pts,routeCurve(T,pts),undefined,undefined,p=>plots.push(p));
check(office.OFFICE_LOT_ID==='block--183--37','exact office allowlist');const p=plots.find(p=>p.id===office.OFFICE_LOT_ID);check(p?.kind==='office'&&p.width===11&&p.depth===11&&p.height===31.5,'existing descriptor');
const g=office.createOfficeSlice(p),shared=townhouseMaterials(),maps=new Set();check(g.children.length===3,'three buckets');let triangles=0;
for(const [k,m]of g.children.entries()){check(m.isMesh&&m.material===(k===2?shared.glass:shared.architecture),'shared material identity');check(m.castShadow===(k===0)&&m.receiveShadow&&m.frustumCulled,'render policy');check(m.geometry.boundingBox&&m.geometry.boundingSphere,'bounds');const a=m.geometry.attributes;triangles+=a.position.count/3;for(const [key,size]of [['position',3],['normal',3],['uv',2],['aSurface',1],['color',3]])check(a[key]?.count===a.position.count&&a[key].itemSize===size,'attribute '+key);for(let i=0;i<a.position.count;i++){check(Math.abs(a.position.getX(i))<=p.width/2+.0001&&Math.abs(a.position.getZ(i))<=p.depth/2+.0001&&a.position.getY(i)>=0&&a.position.getY(i)<=p.height,'lot bounds');check(Math.abs(new T.Vector3().fromBufferAttribute(a.normal,i).length()-1)<.0001,'unit normals');}for(let i=0;i<a.position.count;i+=6){const d=new T.Vector3().fromBufferAttribute(a.position,i).distanceTo(new T.Vector3().fromBufferAttribute(a.position,i+1)),uv=new T.Vector2().fromBufferAttribute(a.uv,i).distanceTo(new T.Vector2().fromBufferAttribute(a.uv,i+1));check(Math.abs(d-uv)<.0001,'metric UVs');}Object.values(m.material).forEach(v=>{if(v?.isTexture)maps.add(v)});}
check(triangles<=6000&&maps.size===4,'slice budget');check(g.userData.recipe.reveal>=.25&&g.userData.recipe.lobbyHeight>=3.5,'office depth/lobby');
const fp=o=>{const a=[];o.traverse(m=>{if(m.isMesh)a.push({name:m.name,position:m.position.toArray(),cast:m.castShadow,material:m.material.uuid,attributes:Object.fromEntries(Object.entries(m.geometry.attributes).map(([k,v])=>[k,Array.from(v.array)])),instances:m.instanceMatrix?Array.from(m.instanceMatrix.array):null,colors:m.instanceColor?Array.from(m.instanceColor.array):null})});return JSON.stringify(a)};
check(fp(g)===fp(office.createOfficeSlice(p)),'determinism');const city=legacyCity(plots),selected=city.getObjectByName(p.id);check(selected?.userData.archetype==='office-slice','integration');check(city.children.filter(o=>o.userData.archetype==='office-slice').length===1,'single replacement');const rest=new T.Group();city.children.filter(o=>o!==selected).forEach(o=>rest.add(o.clone()));check(fp(rest)===fp(legacyCity(plots.filter(o=>o.id!==p.id))),'all other buildings unchanged');let disposed=0;selected.children.forEach(m=>m.geometry.addEventListener('dispose',()=>disposed++));city.userData.dispose();city.userData.dispose();check(disposed===3,'owned geometry disposed once');let rejected=false;try{office.createOfficeSlice({...p,kind:'midrise'})}catch(e){rejected=e instanceof TypeError}check(rejected,'descriptor validation');
return {pass:true,id:p.id,plot:p,renderables:3,triangles,materials:2,maps:maps.size,recipe:g.userData.recipe};})()''')
print(result)
assert isinstance(result,dict) and result.get('pass'),result
